import * as React from 'react';
import { describe, it, afterEach, afterAll, vi } from 'vitest';
import { render, screen, fireEvent, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as BaseFieldControl } from './BaseFieldControl';

// Observational probe: records behavior of the reviewed head (`Field.Control`) and of the
// review base (`BaseFieldControl`, a verbatim copy of main's FieldControl.tsx with only its
// relative import paths rewritten). No hypothesis assertions, results are printed at the end.

const results: Record<string, unknown> = {};
const variants: Array<[string, React.ComponentType<any>]> = [
  ['head', Field.Control as any],
  ['base', BaseFieldControl as any],
];

const SERVER_ERRORS = { message: 'Server error' };

afterEach(() => {
  cleanup();
});

afterAll(() => {
  // eslint-disable-next-line no-console
  console.log(`PROBE_RESULTS ${JSON.stringify(results, null, 2)}`);
});

function attr(el: Element, name: string) {
  return el.hasAttribute(name);
}

describe.each(variants)('%s', (label, Control) => {
  function record(key: string, value: unknown) {
    results[`${label}:${key}`] = value;
  }

  function measureRenders(
    validationMode: 'onChange' | 'onSubmit' | 'onBlur' | undefined,
    controlled: boolean,
  ) {
    const count = { current: 0 };
    const validate = () => null;

    function App() {
      const [value, setValue] = React.useState('');
      const controlProps = controlled ? { value, onValueChange: setValue } : {};
      return (
        <Field.Root validationMode={validationMode} validate={validate}>
          <Control
            data-testid="control"
            {...controlProps}
            render={(props: any) => {
              count.current += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }

    render(<App />);
    const control = screen.getByTestId('control');
    fireEvent.change(control, { target: { value: 'a' } });
    const settled = count.current;
    fireEvent.change(control, { target: { value: 'ab' } });
    fireEvent.change(control, { target: { value: 'abc' } });
    const delta = count.current - settled;
    cleanup();
    return delta;
  }

  it('S1 render counts for two steady-state keystrokes', () => {
    record('S1 controlled default-mode renders/2 keystrokes', measureRenders(undefined, true));
    record('S1 controlled onChange-mode renders/2 keystrokes', measureRenders('onChange', true));
    record(
      'S1 uncontrolled onChange-mode renders/2 keystrokes',
      measureRenders('onChange', false),
    );
  });

  it('S2 focused latch when disabled or unmounted while focused', () => {
    function App() {
      const [disabled, setDisabled] = React.useState(false);
      const [mounted, setMounted] = React.useState(true);
      return (
        <div>
          <Field.Root data-testid="root">
            {mounted && <Control data-testid="control" disabled={disabled} />}
          </Field.Root>
          <button type="button" onClick={() => setDisabled(true)}>
            disable
          </button>
          <button type="button" onClick={() => setMounted(false)}>
            unmount
          </button>
        </div>
      );
    }

    render(<App />);
    const root = screen.getByTestId('root');
    act(() => {
      screen.getByTestId('control').focus();
    });
    record('S2 focused after focus()', attr(root, 'data-focused'));
    fireEvent.click(screen.getByText('disable'));
    record('S2 data-focused after disabled while focused', attr(root, 'data-focused'));
    cleanup();

    render(<App />);
    const root2 = screen.getByTestId('root');
    act(() => {
      screen.getByTestId('control').focus();
    });
    fireEvent.click(screen.getByText('unmount'));
    record('S2 data-focused after unmount while focused', attr(root2, 'data-focused'));
  });

  it('S3 programmatic controlled change and a Form server error', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={SERVER_ERRORS}>
          <Field.Root name="message">
            <Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
          <button type="button" onClick={() => setValue('external')}>
            set
          </button>
        </Form>
      );
    }

    render(<App />);
    record('S3 server error shown initially', screen.queryByText('Server error') !== null);
    fireEvent.click(screen.getByText('set'));
    record(
      'S3 server error shown after programmatic change',
      screen.queryByText('Server error') !== null,
    );
    cleanup();

    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'typed' } });
    record(
      'S3 server error shown after user typing (controlled)',
      screen.queryByText('Server error') !== null,
    );
  });

  it('S4 programmatic reset: dirty, filled, resolved error', () => {
    const validate = vi.fn((value: unknown) => (value === 'bad' ? 'Bad value' : null));

    function App() {
      const [value, setValue] = React.useState('init');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control value={value} onValueChange={setValue} />
          <Field.Error />
          <button type="button" onClick={() => setValue('init')}>
            reset
          </button>
          <button type="button" onClick={() => setValue('')}>
            clear
          </button>
          <button type="button" onClick={() => setValue('good')}>
            good
          </button>
        </Field.Root>
      );
    }

    render(<App />);
    const root = screen.getByTestId('root');
    const control = screen.getByRole('textbox');
    record('S4 filled on mount (controlled non-empty)', attr(root, 'data-filled'));
    record('S4 dirty on mount', attr(root, 'data-dirty'));

    fireEvent.change(control, { target: { value: 'bad' } });
    record('S4 dirty after typing', attr(root, 'data-dirty'));
    record('S4 invalid after typing bad', attr(root, 'data-invalid'));

    fireEvent.click(screen.getByText('good'));
    record('S4 invalid after programmatic good', attr(root, 'data-invalid'));
    record('S4 error text after programmatic good', screen.queryByText('Bad value') !== null);

    fireEvent.click(screen.getByText('reset'));
    record('S4 dirty after programmatic reset to initial', attr(root, 'data-dirty'));

    fireEvent.click(screen.getByText('clear'));
    record('S4 filled after programmatic clear', attr(root, 'data-filled'));
    record('S4 dirty after programmatic clear', attr(root, 'data-dirty'));
  });

  it('S5 controlled change that is canceled but still applied by the consumer', () => {
    const validate = vi.fn(() => null);

    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control
            value={value}
            onValueChange={(next: string, details: any) => {
              details.cancel();
              setValue(next);
            }}
          />
        </Field.Root>
      );
    }

    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    record('S5 validate calls (controlled, canceled, value applied)', validate.mock.calls.length);
    record('S5 dirty', attr(screen.getByTestId('root'), 'data-dirty'));
  });

  it('S5b uncontrolled canceled change: dirty and filled', () => {
    const validate = vi.fn(() => null);
    render(
      <Form errors={SERVER_ERRORS}>
        <Field.Root name="message" data-testid="root" validationMode="onChange" validate={validate}>
          <Control onValueChange={(next: string, details: any) => details.cancel()} />
          <Field.Error />
        </Field.Root>
      </Form>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    record('S5b validate calls (uncontrolled canceled)', validate.mock.calls.length);
    record('S5b dirty (uncontrolled canceled)', attr(root, 'data-dirty'));
    record('S5b filled (uncontrolled canceled)', attr(root, 'data-filled'));
    record(
      'S5b server error kept (uncontrolled canceled)',
      screen.queryByText('Server error') !== null,
    );
  });

  it('S6 controlled change whose native event is default-prevented', () => {
    const validate = vi.fn(() => null);

    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={SERVER_ERRORS}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }

    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), {
      capture: true,
      once: true,
    });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    record('S6 validate calls (controlled, prevented)', validate.mock.calls.length);
    record('S6 server error kept (controlled, prevented)', screen.queryByText('Server error') !== null);
  });

  it('S8 controlled value the consumer rejects', () => {
    const validate = vi.fn(() => null);
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Control value="" onValueChange={() => {}} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'x' } });
    const root = screen.getByTestId('root');
    record('S8 validate calls (rejected)', validate.mock.calls.length);
    record('S8 dirty (rejected)', attr(root, 'data-dirty'));
    record('S8 filled (rejected)', attr(root, 'data-filled'));
    record('S8 DOM value (rejected)', screen.getByRole<HTMLInputElement>('textbox').value);
  });

  it('S9 controlled value the consumer rewrites', () => {
    const validate = vi.fn((_value: unknown) => null);

    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={validate}>
          <Control value={value} onValueChange={(next: string) => setValue(next.toUpperCase())} />
        </Field.Root>
      );
    }

    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    record(
      'S9 validate args (rewritten to upper case)',
      validate.mock.calls.map((call) => call[0]),
    );
  });

  it('S10 stale async validator after a programmatic change', async () => {
    let resolveOld: (value: string | null) => void = () => {};
    const validate = vi.fn((value: unknown) => {
      if (value === 'old') {
        return new Promise<string | null>((resolve) => {
          resolveOld = resolve;
        });
      }
      return null;
    });

    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control value={value} onValueChange={setValue} />
          <Field.Error />
          <button type="button" onClick={() => setValue('new')}>
            set
          </button>
        </Field.Root>
      );
    }

    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'old' } });
    fireEvent.click(screen.getByText('set'));
    await act(async () => {
      resolveOld('Old error');
      await Promise.resolve();
      await Promise.resolve();
    });
    record('S10 stale async error published', screen.queryByText('Old error') !== null);
    record(
      'S10 validate args',
      validate.mock.calls.map((call) => call[0]),
    );
  });

  it('S11 numeric and array controlled values return to not-dirty', () => {
    function App() {
      const [value, setValue] = React.useState<any>(['a', 'b']);
      return (
        <Field.Root data-testid="root">
          <Control value={value} onValueChange={(next: string) => setValue(next.split(','))} />
        </Field.Root>
      );
    }

    render(<App />);
    const root = screen.getByTestId('root');
    const control = screen.getByRole<HTMLInputElement>('textbox');
    record('S11 array DOM value', control.value);
    record('S11 array dirty on mount', attr(root, 'data-dirty'));
    fireEvent.change(control, { target: { value: 'a,b,c' } });
    record('S11 array dirty after edit', attr(root, 'data-dirty'));
    fireEvent.change(control, { target: { value: 'a,b' } });
    record('S11 array dirty after returning to initial', attr(root, 'data-dirty'));
  });
});

