import * as React from 'react';
import { afterAll, afterEach, describe, it } from 'vitest';
import { render, screen, fireEvent, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { FieldControl as BaseFieldControl } from './BaseFieldControl';

const observations: Record<string, unknown> = {};

const variants: Array<[string, React.ElementType]> = [
  ['head', Field.Control],
  ['base', BaseFieldControl],
];

afterEach(() => {
  cleanup();
});

afterAll(() => {
  // eslint-disable-next-line no-console
  console.log(`OBSERVATIONS ${JSON.stringify(observations, null, 2)}`);
});

function snapshot() {
  const root = screen.getByTestId('root');
  const control = screen.getByTestId('control') as HTMLInputElement;
  return {
    domValue: control.value,
    rootInvalid: root.hasAttribute('data-invalid'),
    rootValid: root.hasAttribute('data-valid'),
    ariaInvalid: control.getAttribute('aria-invalid'),
    errorText: screen.queryByTestId('error')?.textContent ?? null,
    customValidity: control.validationMessage,
  };
}

describe.each(variants)('%s', (label, Control) => {
  it('onBlur validation + normalize-on-blur (sync validator)', async () => {
    const calls: unknown[] = [];
    const validate = (v: unknown) => {
      calls.push(v);
      return String(v).trim().length < 3 ? 'too short' : null;
    };

    function App({ trim }: { trim: boolean }) {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onBlur" validate={validate}>
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            onBlur={() => {
              if (trim) {
                setValue((v: string) => v.trim());
              }
            }}
          />
          <Field.Error data-testid="error" />
        </Field.Root>
      );
    }

    for (const trim of [false, true]) {
      calls.length = 0;
      render(<App trim={trim} />);
      const control = screen.getByTestId('control');
      fireEvent.focus(control);
      fireEvent.change(control, { target: { value: 'a ' } });
      fireEvent.blur(control);
      // eslint-disable-next-line no-await-in-loop
      await act(async () => {});
      observations[`${label} sync onBlur trim=${trim}`] = { ...snapshot(), validateCalls: [...calls] };
      cleanup();
    }
  });

  it('onBlur validation + normalize-on-blur (async validator)', async () => {
    const calls: unknown[] = [];
    const validate = async (v: unknown) => {
      calls.push(v);
      await new Promise((resolve) => {
        setTimeout(resolve, 20);
      });
      return 'taken';
    };

    function App({ trim }: { trim: boolean }) {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onBlur" validate={validate}>
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            onBlur={() => {
              if (trim) {
                setValue((v: string) => v.trim());
              }
            }}
          />
          <Field.Error data-testid="error" />
        </Field.Root>
      );
    }

    for (const trim of [false, true]) {
      calls.length = 0;
      render(<App trim={trim} />);
      const control = screen.getByTestId('control');
      fireEvent.focus(control);
      fireEvent.change(control, { target: { value: 'a ' } });
      fireEvent.blur(control);
      // eslint-disable-next-line no-await-in-loop
      await act(async () => {
        await new Promise((resolve) => {
          setTimeout(resolve, 80);
        });
      });
      observations[`${label} async onBlur trim=${trim}`] = { ...snapshot(), validateCalls: [...calls] };
      cleanup();
    }
  });

  it('render count per keystroke, controlled', async () => {
    for (const mode of ['onSubmit', 'onChange', 'onBlur'] as const) {
      const count = { current: 0 };
      const validate = () => null;

      function App() {
        const [value, setValue] = React.useState('');
        return (
          <Field.Root data-testid="root" validationMode={mode} validate={validate}>
            <Control
              data-testid="control"
              value={value}
              onValueChange={setValue}
              render={(props: any) => {
                count.current += 1;
                return <input {...props} />;
              }}
            />
          </Field.Root>
        );
      }

      render(<App />);
      const control = screen.getByTestId('control');
      fireEvent.change(control, { target: { value: 'a' } });
      const settled = count.current;
      fireEvent.change(control, { target: { value: 'ab' } });
      fireEvent.change(control, { target: { value: 'abc' } });
      observations[`${label} renders per steady keystroke mode=${mode}`] = (count.current - settled) / 2;
      cleanup();
    }
  });
});

