import * as React from 'react';
import { it, describe, vi, afterEach } from 'vitest';
import { render, screen, fireEvent, act, cleanup } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { Input } from '@base-ui/react/input';
import { Combobox } from '@base-ui/react/combobox';

const variant = process.env.FC_BASE === '1' ? 'BASE' : 'HEAD';

function report(name: string, data: unknown) {
  // eslint-disable-next-line no-console
  console.log(`RESULT[${variant}] ${name}: ${JSON.stringify(data)}`);
}

afterEach(() => {
  cleanup();
});

describe('probe', () => {
  it('1. renders per keystroke, controlled', () => {
    for (const mode of ['onSubmit', 'onChange'] as const) {
      let count = 0;
      function App() {
        const [value, setValue] = React.useState('');
        return (
          <Field.Root validationMode={mode} validate={() => null}>
            <Field.Control
              data-testid="control"
              value={value}
              onValueChange={setValue}
              render={(props) => {
                count += 1;
                return <input {...props} />;
              }}
            />
          </Field.Root>
        );
      }
      render(<App />);
      const control = screen.getByTestId('control');
      fireEvent.change(control, { target: { value: 'a' } });
      const settled = count;
      fireEvent.change(control, { target: { value: 'ab' } });
      fireEvent.change(control, { target: { value: 'abc' } });
      report(`renders for 2 steady keystrokes (${mode})`, count - settled);
      cleanup();
    }
  });

  it('2. remount keyed controlled control with empty value', () => {
    function App() {
      const [step, setStep] = React.useState(0);
      return (
        <Field.Root data-testid="root">
          {step === 0 ? (
            <Field.Control key="a" value="foo" onValueChange={() => {}} />
          ) : (
            <Field.Control key="b" value="" onValueChange={() => {}} />
          )}
          <button type="button" onClick={() => setStep(1)}>
            next
          </button>
        </Field.Root>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    const before = root.hasAttribute('data-filled');
    fireEvent.click(screen.getByRole('button'));
    report('filled before/after swap to empty controlled control', {
      before,
      after: root.hasAttribute('data-filled'),
      inputValue: (screen.getByRole('textbox') as HTMLInputElement).value,
    });
  });

  it('3. focus latch on disable / unmount', () => {
    function App() {
      const [disabled, setDisabled] = React.useState(false);
      const [shown, setShown] = React.useState(true);
      return (
        <Field.Root data-testid="root">
          {shown && <Field.Control disabled={disabled} />}
          <button type="button" onClick={() => setDisabled(true)}>
            disable
          </button>
          <button type="button" onClick={() => setShown(false)}>
            hide
          </button>
        </Field.Root>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    act(() => {
      screen.getByRole('textbox').focus();
    });
    const focusedBefore = root.hasAttribute('data-focused');
    fireEvent.click(screen.getByText('disable'));
    const afterDisable = root.hasAttribute('data-focused');
    cleanup();

    render(<App />);
    const root2 = screen.getByTestId('root');
    act(() => {
      screen.getByRole('textbox').focus();
    });
    fireEvent.click(screen.getByText('hide'));
    report('data-focused', {
      focusedBefore,
      afterDisable,
      afterUnmount: root2.hasAttribute('data-focused'),
    });
  });

  it('4. programmatic change and Form errors', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="button" onClick={() => setValue('x')}>
            set
          </button>
        </Form>
      );
    }
    render(<App />);
    const before = screen.queryByTestId('error')?.textContent ?? null;
    fireEvent.click(screen.getByText('set'));
    report('form error before/after programmatic change', {
      before,
      after: screen.queryByTestId('error')?.textContent ?? null,
    });
  });

  it('5. combobox inline with field-aware Input, object items', async () => {
    const validate = vi.fn((_value: unknown) => null);
    const items = [
      { value: 'fr', label: 'France' },
      { value: 'de', label: 'Germany' },
    ];
    const user = userEvent.setup();
    render(
      <Field.Root name="country" data-testid="root" validationMode="onChange" validate={validate}>
        <Combobox.Root items={items}>
          <Combobox.Input render={<Input data-testid="input" />} />
          <Combobox.Portal>
            <Combobox.Positioner>
              <Combobox.Popup>
                <Combobox.List>
                  {(item: (typeof items)[number]) => (
                    <Combobox.Item key={item.value} value={item}>
                      {item.label}
                    </Combobox.Item>
                  )}
                </Combobox.List>
              </Combobox.Popup>
            </Combobox.Positioner>
          </Combobox.Portal>
        </Combobox.Root>
      </Field.Root>,
    );
    const input = screen.getByTestId('input') as HTMLInputElement;
    const root = screen.getByTestId('root');
    await user.click(input);
    await user.click(await screen.findByRole('option', { name: 'France' }));
    report('combobox select: validate args', {
      calls: validate.mock.calls.map((c) => c[0]),
      inputValue: input.value,
      dirty: root.hasAttribute('data-dirty'),
      filled: root.hasAttribute('data-filled'),
    });
    validate.mockClear();
    await user.click(document.body);
    report('combobox after outside click: validate args', {
      calls: validate.mock.calls.map((c) => c[0]),
      inputValue: input.value,
      dirty: root.hasAttribute('data-dirty'),
      filled: root.hasAttribute('data-filled'),
    });
  });

  it('6. submit-time validate argument type for numeric controlled value', () => {
    const validate = vi.fn((_value: unknown) => null);
    render(
      <Form onSubmit={(event) => event.preventDefault()}>
        <Field.Root name="n" validate={validate}>
          <Field.Control value={5} onValueChange={() => {}} />
        </Field.Root>
        <button type="submit">submit</button>
      </Form>,
    );
    fireEvent.click(screen.getByText('submit'));
    report('submit validate arg types', validate.mock.calls.map((c) => typeof c[0]));
  });

  it('7. uncontrolled cancel still updates dirty/filled', () => {
    const validate = vi.fn((_value: unknown) => null);
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control onValueChange={(_v, details) => details.cancel()} />
      </Field.Root>,
    );
    const root = screen.getByTestId('root');
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    report('uncontrolled cancel', {
      validateCalls: validate.mock.calls.length,
      dirty: root.hasAttribute('data-dirty'),
      filled: root.hasAttribute('data-filled'),
    });
  });

  it('8. controlled, consumer leaves value unchanged while native validity changes', () => {
    const validate = vi.fn((_value: unknown) => null);
    function App() {
      const [value, setValue] = React.useState('abc');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control
            value={value}
            onValueChange={(next) => setValue(next.trim() === '' ? value : next)}
          />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: '' } });
    report('controlled rejected change', {
      validateCalls: validate.mock.calls.length,
      inputValue: (screen.getByRole('textbox') as HTMLInputElement).value,
      dirty: screen.getByTestId('root').hasAttribute('data-dirty'),
    });
  });
});

