import * as React from 'react';
import { appendFileSync } from 'node:fs';
import { it, describe, afterEach } from 'vitest';
import { render, screen, fireEvent, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { Input } from '@base-ui/react/input';
import { NumberField } from '@base-ui/react/number-field';
import { Combobox } from '@base-ui/react/combobox';

const variant = process.env.FC_BASE === '1' ? 'BASE' : 'HEAD';

function report(name: string, data: unknown) {
  appendFileSync(
    `${__dirname}/results-${variant}.txt`,
    `RESULT[${variant}] ${name}: ${JSON.stringify(data)}\n`,
  );
}

function snap(rootId = 'root', inputId = 'input', errorId = 'error') {
  const root = screen.queryByTestId(rootId);
  const input = screen.queryByTestId(inputId) as HTMLInputElement | null;
  return {
    inputValue: input?.value ?? null,
    ariaInvalid: input?.getAttribute('aria-invalid') ?? null,
    rootInvalid: root?.hasAttribute('data-invalid') ?? null,
    rootValid: root?.hasAttribute('data-valid') ?? null,
    rootDirty: root?.hasAttribute('data-dirty') ?? null,
    rootFilled: root?.hasAttribute('data-filled') ?? null,
    rootFocused: root?.hasAttribute('data-focused') ?? null,
    error: screen.queryByTestId(errorId)?.textContent ?? null,
  };
}

afterEach(() => {
  cleanup();
});

describe('validator', () => {
  it('F1-S1 required controlled, default mode, onFormSubmit clears value', () => {
    function App() {
      const [text, setText] = React.useState('');
      return (
        <Form onFormSubmit={() => setText('')}>
          <Field.Root name="todo" data-testid="root">
            <Field.Control data-testid="input" required value={text} onValueChange={setText} />
            <Field.Error data-testid="error" match="valueMissing">
              Required
            </Field.Error>
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByTestId('input'), { target: { value: 'milk' } });
    const beforeSubmit = snap();
    fireEvent.click(screen.getByText('submit'));
    report('F1-S1', { beforeSubmit, afterSubmit: snap() });
  });

  it('F1-S2 required controlled, onChange mode, type then reset from code', () => {
    function App() {
      const [text, setText] = React.useState('');
      return (
        <Field.Root name="todo" data-testid="root" validationMode="onChange">
          <Field.Control data-testid="input" required value={text} onValueChange={setText} />
          <Field.Error data-testid="error" match="valueMissing">
            Required
          </Field.Error>
          <button type="button" onClick={() => setText('')}>
            reset
          </button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByTestId('input'), { target: { value: 'milk' } });
    const afterType = snap();
    fireEvent.click(screen.getByText('reset'));
    report('F1-S2', { afterType, afterReset: snap() });
  });

  it('F1-S3 required controlled, default mode, never submitted, never typed: set then clear from code', () => {
    function App() {
      const [text, setText] = React.useState('');
      return (
        <Field.Root name="todo" data-testid="root">
          <Field.Control data-testid="input" required value={text} onValueChange={setText} />
          <Field.Error data-testid="error" match="valueMissing">
            Required
          </Field.Error>
          <button type="button" onClick={() => setText('x')}>
            set
          </button>
          <button type="button" onClick={() => setText('')}>
            reset
          </button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('set'));
    fireEvent.click(screen.getByText('reset'));
    report('F1-S3', snap());
  });

  it('F2-A onBlur mode, sync validator, onBlur trims the controlled value', () => {
    const seen: unknown[] = [];
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(value) => {
            seen.push(value);
            return String(value).trim().length < 3 ? 'too short' : null;
          }}
        >
          <Field.Control
            data-testid="input"
            value={v}
            onValueChange={setV}
            onBlur={() => setV((p) => p.trim())}
          />
          <Field.Error data-testid="error" />
        </Field.Root>
      );
    }
    render(<App />);
    const input = screen.getByTestId('input');
    fireEvent.focus(input);
    fireEvent.change(input, { target: { value: 'a ' } });
    fireEvent.blur(input);
    report('F2-A', { ...snap(), validateArgs: seen.slice() });
  });

  it('F2-A0 control: same without the trim', () => {
    const seen: unknown[] = [];
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(value) => {
            seen.push(value);
            return String(value).trim().length < 3 ? 'too short' : null;
          }}
        >
          <Field.Control data-testid="input" value={v} onValueChange={setV} />
          <Field.Error data-testid="error" />
        </Field.Root>
      );
    }
    render(<App />);
    const input = screen.getByTestId('input');
    fireEvent.focus(input);
    fireEvent.change(input, { target: { value: 'a ' } });
    fireEvent.blur(input);
    report('F2-A0', { ...snap(), validateArgs: seen.slice() });
  });

  it('F2-B onBlur mode, invalid after blur, code sets another invalid value', () => {
    const seen: unknown[] = [];
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(value) => {
            seen.push(value);
            return String(value).trim().length < 3 ? 'too short' : null;
          }}
        >
          <Field.Control data-testid="input" value={v} onValueChange={setV} />
          <Field.Error data-testid="error" />
          <button type="button" onClick={() => setV('x')}>
            set
          </button>
        </Field.Root>
      );
    }
    render(<App />);
    const input = screen.getByTestId('input');
    fireEvent.focus(input);
    fireEvent.change(input, { target: { value: 'ab' } });
    fireEvent.blur(input);
    const afterBlur = snap();
    fireEvent.click(screen.getByText('set'));
    report('F2-B', { afterBlur, afterSet: snap(), validateArgs: seen.slice() });
  });

  it('F2-C onBlur mode, async validator, onBlur trims', async () => {
    const seen: unknown[] = [];
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(value) => {
            seen.push(value);
            return new Promise<string | null>((resolve) => {
              setTimeout(() => resolve('taken'), 20);
            });
          }}
        >
          <Field.Control
            data-testid="input"
            value={v}
            onValueChange={setV}
            onBlur={() => setV((p) => p.trim())}
          />
          <Field.Error data-testid="error" />
        </Field.Root>
      );
    }
    render(<App />);
    const input = screen.getByTestId('input');
    fireEvent.focus(input);
    fireEvent.change(input, { target: { value: 'a ' } });
    fireEvent.blur(input);
    await act(async () => {
      await new Promise((resolve) => {
        setTimeout(resolve, 80);
      });
    });
    report('F2-C', { ...snap(), validateArgs: seen.slice() });
  });

  for (const mode of [undefined, 'onBlur', 'onChange'] as const) {
    it(`F4 render count per keystroke, controlled, mode=${String(mode)}`, () => {
      const renderCountRef = { current: 0 };
      let validateCalls = 0;
      function App() {
        const [value, setValue] = React.useState('');
        return (
          <Field.Root
            validationMode={mode}
            validate={() => {
              validateCalls += 1;
              return null;
            }}
          >
            <Field.Control
              data-testid="input"
              value={value}
              onValueChange={setValue}
              render={(props) => {
                renderCountRef.current += 1;
                return <input {...props} />;
              }}
            />
          </Field.Root>
        );
      }
      render(<App />);
      const input = screen.getByTestId('input');
      fireEvent.change(input, { target: { value: 'a' } });
      const settled = renderCountRef.current;
      fireEvent.change(input, { target: { value: 'ab' } });
